import type { DocBlock, LibraryDoc } from "../types";

const h1 = (text: string): DocBlock => ({ t: "h1", text });
const h2 = (text: string): DocBlock => ({ t: "h2", text });
const p = (text: string): DocBlock => ({ t: "p", text });
const li = (text: string): DocBlock => ({ t: "li", text });
const step = (text: string): DocBlock => ({ t: "step", text });
const field = (label: string, hint?: string): DocBlock => (hint ? { t: "field", label, hint } : { t: "field", label });
const table = (headers: string[], rows: string[][]): DocBlock => ({ t: "table", headers, rows });
const blank = (n: number, cols: number): string[][] => Array.from({ length: n }, () => Array<string>(cols).fill(""));

